// จัดกลุ่ม event ตาม lead + คำนวณ Engagement Score ตามตารางคะแนนของสเปก
// page_view+1 | return_visit+5 | video_view+3 | ดูเกิน 50%+5 | ดูจบ+8 | ดูคลิปเดิมซ้ำ+5
// form_open+5 | form_submit+20 | เลือกหัวข้อ+10 | ขอให้ติดต่อกลับ+30
const res = $input.first().json || {};
const events = Array.isArray(res) ? res : (res.events || res.data || res.items || []);
const by = {};
for (const e of events) {
  const pid = e.prospectId || e.prospect_id || e.visitorId || e.visitor_id;
  if (!pid) continue;
  const g = by[pid] || (by[pid] = { prospectId: pid, events: [], videos: {}, counts: {}, lastSeenAt: null });
  const at = e.at || e.occurredAt || e.createdAt || null;
  if (at && (!g.lastSeenAt || at > g.lastSeenAt)) g.lastSeenAt = at;
  g.events.push({ type: String(e.type || ''), videoId: e.videoId || e.video_id || null, watchPct: Number(e.watchPct || e.watch_pct || 0) || 0 });
}
const out = [];
for (const pid of Object.keys(by)) {
  const g = by[pid];
  let score = 0;
  for (const e of g.events) {
    g.counts[e.type] = (g.counts[e.type] || 0) + 1;
    if (e.type === 'page_view') score += 1;
    if (e.type === 'return_visit') score += 5;
    if (e.type === 'video_view') { score += 3; if (e.videoId) g.videos[e.videoId] = (g.videos[e.videoId] || 0) + 1; }
    if (e.watchPct > 50) score += 5;
    if (e.watchPct >= 95 || e.type === 'video_complete') score += 8;
    if (e.type === 'form_open') score += 5;
    if (e.type === 'form_submit') score += 20;
    if (e.type === 'topic_select' || e.type === 'topic_choose') score += 10;
    if (e.type === 'callback_request') score += 30;
  }
  const repeatedVideos = Object.keys(g.videos).filter(v => g.videos[v] > 1);
  score += repeatedVideos.length * 5; // ดูคลิปเดิมซ้ำ +5 ต่อคลิป
  score = Math.max(0, Math.min(100, score));
  const level = score >= 70 ? 'HIGH_INTENT' : score >= 40 ? 'INTERESTED' : score >= 20 ? 'WARM' : 'LOW';
  out.push({ json: {
    prospectId: pid, engagementScore: score, level: level,
    behavior: { counts: g.counts, videos: Object.keys(g.videos), repeatedVideos: repeatedVideos, lastSeenAt: g.lastSeenAt, eventCount: g.events.length },
    at: new Date().toISOString()
  } });
}
if (out.length === 0) return [{ json: { none: true, reason: 'ไม่พบ event ใหม่ในช่วงเวลานี้' } }];
return out;

// อ่านผล AI Interest Analyst (JSON) — ถ้า AI ล้มเหลว/ตอบไม่เป็น JSON ยังบันทึกคะแนนที่คำนวณเองต่อได้
const leads = $('จัดกลุ่มตาม Lead + คำนวณคะแนน').all();
const items = $input.all();
const out = [];
items.forEach(function (it, i) {
  const lead = (leads[i] && leads[i].json) || {};
  if (lead.none || lead.prospectId === undefined) return;
  const raw = String(it.json.answer || it.json.text || it.json.content || '');
  const m = raw.match(/\{[\s\S]*\}/);
  let parsed = null;
  if (m) { try { parsed = JSON.parse(m[0]); } catch (e) { parsed = null; } }
  const topics = (parsed && Array.isArray(parsed.topics)) ? parsed.topics.slice(0, 5).map(function (t) {
    return { topic: String(t.topic || t.name || '').slice(0, 80), weight: Math.max(0, Math.min(100, Number(t.weight || t.score || 0) || 0)) };
  }) : [];
  out.push({ json: {
    prospectId: lead.prospectId, engagementScore: lead.engagementScore, level: lead.level,
    behavior: lead.behavior, topics: topics,
    aiOk: !!parsed,
    aiSummary: (parsed && (parsed.summaryThai || parsed.summary)) ? String(parsed.summaryThai || parsed.summary).slice(0, 400) : null,
    aiSuggestedAction: (parsed && parsed.suggestedAction) ? String(parsed.suggestedAction).slice(0, 200) : null,
    aiError: parsed ? null : 'AI ตอบไม่ใช่ JSON ที่อ่านได้ (บันทึกคะแนนที่คำนวณเองต่อไป)',
    at: new Date().toISOString()
  } });
});
if (out.length === 0) return [{ json: { none: true, reason: 'ไม่มี lead ให้วิเคราะห์ในรอบนี้' } }];
return out;

// สรุปผลการอัปเดตคะแนน/ความสนใจ
const all = $('บันทึกความสนใจ + Engagement Score (/api/lead/score)').all();
let okCount = 0, failCount = 0, firstError = null;
for (const it of all) {
  const j = it.json || {};
  const c = j.statusCode === undefined ? null : Number(j.statusCode);
  const ok = j.ok === true || (c !== null && c >= 200 && c < 300);
  if (ok) okCount++;
  else { failCount++; if (!firstError) firstError = String(j.error || j.message || ('HTTP ' + c)).slice(0, 300); }
}
return [{ json: {
  ok: failCount === 0, workflow: '03-behavior-analyzer', stage: 'update_score',
  detail: 'อัปเดต lead สำเร็จ ' + okCount + ' ราย / ล้มเหลว ' + failCount + ' ราย' + (firstError ? ' — ' + firstError : ''),
  total: all.length, succeeded: okCount, failed: failCount, firstError: firstError,
  alertText: (failCount === 0 ? 'Behavior Analyzer รอบล่าสุดสำเร็จ ' : 'แจ้งเตือน: Behavior Analyzer ล้มเหลว ') + okCount + ' ราย',
  at: new Date().toISOString()
} }];
